# Bayo's Study Court: Algebra 1, Biology, World History (Tennessee 9th-grade basics).
# Slide:  {"h","say","steps":[..],"tip","vis"}   steps are revealed one at a time and read out loud.
# mc:     first choice is the right one (the app shuffles). why[k] explains wrong choice k.
# order:  items listed in the correct order (the app shuffles).
# vis:    {"graph":{"lines":[[m,b],..],"quad":[a,b,c],"pts":[[x,y],..]}}  or  {"punnett":["Bb","bb"]}

def slide(h, say, steps=None, tip="", vis=None):
    d = {"h": h, "say": say, "tip": tip}
    if steps: d["steps"] = steps
    if vis: d["vis"] = vis
    return d

def mc(prompt, ch, ex, why, s="", vis=None):
    assert len(why) == len(ch) - 1, prompt
    d = {"t": "mc", "s": s, "prompt": prompt, "ch": ch, "a": 0, "ex": ex, "why": [""] + why}
    if vis: d["vis"] = vis
    return d

def order(prompt, items, ex):
    return {"t": "order", "prompt": prompt, "items": items, "ex": ex}

G = lambda *lines, pts=None, quad=None: {"graph": {"lines": [list(l) for l in lines], "pts": pts or [], **({"quad": quad} if quad else {})}}
P = lambda a, b: {"punnett": [a, b]}

